import React, { useEffect, useRef, useState } from 'react';
import { Typography, Snackbar, Alert } from '@mui/material';

export default function ComparativaDesktop({ datosComparativa, filtro, datosCargados }) {

  const reportRef = useRef(null);
  const hasRendered = useRef(false);

  const [open, setOpen] = useState(false);

  // Función para cerrar el Snackbar
  const handleClose = (event, reason) => {
    if (reason === "clickaway") return;
    setOpen(false);
  };

  // Control del Snackbar: solo cuando la API ya cargó y no hay datos suficientes
  useEffect(() => {
    if (datosCargados && (!datosComparativa || datosComparativa.length < 2)) {
      setOpen(true);
    }
  }, [datosComparativa, datosCargados]);

  // Inicializa Stimulsoft solo una vez cuando llegan los datos
  useEffect(() => {
    if (!datosComparativa || datosComparativa.length < 2) return;

     if (!window.Stimulsoft || !window.Stimulsoft.Base) {
      console.log("Stimulsoft aún no está cargado");
      return;
    }
    
    if (hasRendered.current) return;  // Evita múltiples ejecuciones
     hasRendered.current = true;

    // -------------------------------
    // 🔑 LICENCIA Y CONFIGURACIÓN BASE
    // -------------------------------
    const STI_KEY = "";

    window.Stimulsoft.Base.StiLicense.key = STI_KEY;
    window.Stimulsoft.Base.Localization.StiLocalization.addLocalizationFile("/stireport/Localization/es.xml", true);
    window.Stimulsoft.Base.Localization.StiLocalization.setLocalizationFile("/stireport/Localization/es.xml");

    // -------------------------------
    // ⚙ OPCIONES DEL VISOR
    // -------------------------------
    const options = new window.Stimulsoft.Viewer.StiViewerOptions();
    options.appearance.scrollbarsMode = true;
    options.appearance.fullScreenMode = false;
    options.toolbar.showSendEmailButton = false;
    options.toolbar.showPrintButton = true;
    options.toolbar.showSaveButton = true;

    // -------------------------------
    // 📄 CREAR VISOR Y REPORTE
    // -------------------------------
    const viewer = new window.Stimulsoft.Viewer.StiViewer(options, "StiViewer", false);
    const report = new window.Stimulsoft.Report.StiReport();
    report.loadFile("/reports/Comparativa.mrt");

    const datos = prepararDatos(datosComparativa);
    const jsonString = JSON.stringify(datos);
    const dataSet = new window.Stimulsoft.System.Data.DataSet("Comparativa");
    dataSet.readJson(jsonString);

    report.dictionary.databases.clear();
    report.regData(dataSet.dataSetName, "", dataSet);
    report.dictionary.synchronize();

    viewer.report = report;
    viewer.renderHtml("reportContainer");

    // -------------------------------
    // 🎨 ESTILOS PERSONALIZADOS
    // -------------------------------
    setTimeout(() => {
      const elements = document.getElementsByClassName('stiJsViewerForm');
      if (elements.length > 0) {
        Object.assign(elements[0].style, {
          backgroundColor: 'aliceblue',
          position: 'relative',
          zIndex: 11,
          fontSize: '12px',
          left: '444px',
          top: '12px',
          opacity: '1',
          width: '30%',
        });
      }

      const menus = document.getElementsByClassName('stiJsViewerMenu');
      for (let i = 0; i < menus.length; i++) {
        Object.assign(menus[i].style, {
          zIndex: 11,
          position: 'relative',
          width: '220px',
          height: 'auto',
          overflow: 'visible',
          top: '11px',
          opacity: '1',
          backgroundColor: 'aliceblue'
        });
      }

      const viewerDiv = document.getElementById('StiViewer');
      if (viewerDiv) viewerDiv.style.height = '5%';

      const panel = document.getElementById('StiViewerReportPanel');
      if (panel) panel.style.width = '100%';
    }, 300);

   

  }, [datosComparativa, filtro]);

  // -------------------------------
  // FUNCIÓN PARA PREPARAR LOS DATOS
  // -------------------------------
  const prepararDatos = (datosComparativa) => {
    const empresaPrincipal = datosComparativa[1];
    const empresasComparadas = datosComparativa.slice(0);

    const datosReporte = [];
    let obj = { tresEmpresas: false };

    const variedadesUnicas = [
      ...new Map(
        empresaPrincipal.datos.concat(
          ...empresasComparadas.map((empresa) => empresa.datos || [])
        ).map((variedad) => [variedad.codvarie, variedad])
      ).values(),
    ];

    const grupoPorCodprodu = {};

    variedadesUnicas.forEach((variedadUnica) => {
      const variedadPrincipal = empresaPrincipal.datos.find(
        (v) => v.codvarie === variedadUnica.codvarie
      );

      let principalData = {
        cliente: variedadUnica.nomclien,
        filtoVariedad: variedadUnica.filtoVariedad,
        producto: variedadUnica.nomprodu || 'Producto no disponible',
        variedad: variedadUnica.nomvarie || 'Variedad no disponible',
        codempre: empresaPrincipal.codempre,
        nomempre: empresaPrincipal.nomempre,
        codprodu: variedadPrincipal?.codprodu,
        codvarie: variedadPrincipal?.codvarie,
        palets: variedadPrincipal?.totpalet || 0,
        cajas: variedadPrincipal?.numcajas || 0,
        pesoNeto: variedadPrincipal?.pesoneto || 0,
        importe: variedadPrincipal?.importe || 0,
      };

      if (empresasComparadas.length === 2) obj.tresEmpresas = true;

      if (!grupoPorCodprodu[principalData.codprodu]) {
        grupoPorCodprodu[principalData.codprodu] = {
          palets: 0,
          cajas: 0,
          pesoNeto: 0,
          importe: 0
        };
      }

      grupoPorCodprodu[principalData.codprodu].palets += principalData.palets;
      grupoPorCodprodu[principalData.codprodu].cajas += principalData.cajas;
      grupoPorCodprodu[principalData.codprodu].pesoNeto += principalData.pesoNeto;
      grupoPorCodprodu[principalData.codprodu].importe += principalData.importe;

      empresasComparadas.forEach((empresa, index) => {
        const variedadComparada = empresa.datos.find(
          (v) => v.codvarie === variedadUnica.codvarie
        );


        const formatoEspañol = (num) => {
          // Redondear a 2 decimales
          const redondeado = num.toFixed(2);
          // Separar parte entera y decimal
          const partes = redondeado.split('.');
          // Agregar puntos cada 3 dígitos en la parte entera
          partes[0] = partes[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
          // Unir con coma como decimal
          return partes.join(',');
        };

        const porcentaje = (base, valor) => {
          let resultado;
          if (base !== 0) {
            resultado = ((valor - base) / base) * 100;
          } else {
            resultado = valor !== 0 ? 100 : 0;
          }
          return formatoEspañol(resultado);
        };





        principalData[`codempre${index + 1}`] = empresa.codempre;
        principalData[`nomempre${index + 1}`] = empresa.nomempre;
        principalData[`palets${index + 1}`] = variedadComparada?.totpalet || 0;
        principalData[`cajas${index + 1}`] = variedadComparada?.numcajas || 0;
        principalData[`pesoNeto${index + 1}`] = variedadComparada?.pesoneto || 0;
        principalData[`importe${index + 1}`] = variedadComparada?.importe || 0;

        principalData[`porcentajePalets${index + 1}`] = porcentaje(principalData.palets, variedadComparada?.totpalet || 0);
        principalData[`porcentajeCajas${index + 1}`] = porcentaje(principalData.cajas, variedadComparada?.numcajas || 0);
        principalData[`porcentajePesoNeto${index + 1}`] = porcentaje(principalData.pesoNeto, variedadComparada?.pesoneto || 0);
        principalData[`porcentajeImporte${index + 1}`] = porcentaje(principalData.importe, variedadComparada?.importe || 0);
      });

      datosReporte.push(principalData);
    });

    return { Comparativa: datosReporte, condicion: [obj], filtro: [filtro] };
  };

  return (
    <>
      <div style={{ height: "750px", width: "100%", position: "relative" }}>
        <div
          id="reportContainer"
          style={{
            width: "100%",
            height: "100%",
            position: "relative",
            zIndex: 1,
          }}
          ref={reportRef}
        ></div>
      </div>

      {/* 🔔 Snackbar solo si API devolvió pocos o ningún dato */}
      <Snackbar
        open={open}
        autoHideDuration={20000}
        onClose={handleClose}
        anchorOrigin={{ vertical: "top", horizontal: "center" }}
      >
        <Alert onClose={handleClose} severity="info" sx={{ width: "100%" }}>
          No hay datos suficientes para comparar.
        </Alert>
      </Snackbar>
    </>
  );
}
