import React, { useState, useEffect } from 'react';
import { TextField, Autocomplete, Grid, CircularProgress, Typography, Dialog, DialogTitle, DialogContent, DialogActions, Button } from '@mui/material';
import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral';
import ComparativaDesktop from './ComparativaDesktop';
import { leerProductos, leerProductosVariedad } from '../../servicios/Productos';
import { leerVariedades, leerVariedadesProducto } from '../../servicios/Variedades';
import { leerClientes } from '../../servicios/Clientes';
import { leerDatos } from '../../servicios/comparativa';
import { useLocation } from 'react-router-dom';
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { DatePicker, LocalizationProvider } from "@mui/x-date-pickers";
import "dayjs/locale/es";
import dayjs from "dayjs";

export default function ComparativasPagina() {
  const [open, setOpen] = useState(false);
  const [productos, setProductos] = useState([]);
  const [codprodu, setCodProdu] = useState(null);
  const [nomprodu, setNomProdu] = useState(null);
  const [variedades, setVariedades] = useState([]);
  const [codvarie, setCodVarie] = useState(null);
  const [nomvarie, setNomVarie] = useState(null);
  const [clientes, setClientes] = useState([]);
  const [codclien, setCodClien] = useState(null);
  const [nomclien, setNomClien] = useState(null);
  const [datosComparativa, setDatosComparativa] = useState([]);
  const [filtro, setFiltro] = useState({});
  const [loadingComparativa, setLoadingComparativa] = useState(false);
  const [errorComparativa, setErrorComparativa] = useState(null);
  const location = useLocation();
  const [modalAbiertoDesdeURL, setModalAbiertoDesdeURL] = useState(false);
  const [datosCargados, setDatosCargados] = useState(false);


  const [date, setDate] = useState(dayjs().startOf("month"));
  const [hDate, setHDate] = useState(dayjs());
  const [year, setYear] = useState(dayjs());

  const obtenerProductos = async (codvarie) => {
    const { data } = codvarie ? await leerProductosVariedad(codvarie) : await leerProductos();
    setProductos(data);
  };

  const obtenerVariedades = async (val) => {
    const { data } = val ? await leerVariedadesProducto(val) : await leerVariedades();
    setVariedades(data);
  };

  const obtenerClientes = async () => {
    const { data } = await leerClientes();
    setClientes(data);
  };

  const obtenDatosComparativa = async (producto, variedad, cliente, date, hDate) => {
    try {
      setErrorComparativa(null);
      setLoadingComparativa(true);
      let dateFormat = date.format("YYYY-MM-DD");
      let hDateFormat = hDate.format("YYYY-MM-DD");
      const payload = { producto, variedad, cliente, date: dateFormat, hDate: hDateFormat };
      const { data } = await leerDatos(payload);
      if (data.length > 0) setOpen(false); // 🔹 cerrar modal solo si hay datos
      setDatosComparativa(data);
      setDatosCargados(true); // 🔹 marcamos que ya se cargaron datos desde la API
      setFiltro({
        producto: nomprodu || "",
        variedad: nomvarie || "",
        cliente: nomclien || "",
        dFecha: date.format("DD/MM/YYYY") || "",
        hFecha: hDate.format("DD/MM/YYYY") || "",
        anyo: year.year(),
        anyoAnterior: year.subtract(1, "year").year()
      });
    } catch (error) {
      setErrorComparativa(error.message || 'Error al obtener los datos');
    } finally {
      setLoadingComparativa(false);
    }
  };

  const handleChangeProducto = (e, value) => {
    setCodProdu(value?.codprodu || null);
    setNomProdu(value?.nomprodu || "");
    obtenerVariedades(value?.codprodu || null);
  };

  const handleChangeVariedad = (e, value) => {
    setCodVarie(value?.codvarie || null);
    setNomVarie(value?.nomvarie || "");
    obtenerProductos(value?.codvarie || null);
  };

  const handleChangeCliente = (e, value) => {
    setCodClien(value?.codclien || null);
    setNomClien(value?.nomclien || "");
  };

  const openModalComparativa = () => {
    setCodProdu(null);
    setCodVarie(null);
    setCodClien(null);
    setNomProdu(null);
    setNomVarie(null);
    setNomClien(null);
    setDatosComparativa([]);
    setErrorComparativa(null);
    setDatosCargados(false);

    obtenerProductos(null);
    obtenerVariedades(null);
    obtenerClientes();

    setOpen(true);
  };

  useEffect(() => {
    obtenerProductos(null);
    obtenerVariedades(null);
    obtenerClientes();
  }, []);

  useEffect(() => {
    setOpen(false);
    setDatosComparativa([]);
    setModalAbiertoDesdeURL(false);
    setDatosCargados(false);
    const container = document.getElementById("reportContainer");
    if (container) container.innerHTML = "";
  }, [location.pathname, location.search]);

  useEffect(() => {
    if (!modalAbiertoDesdeURL) {
      openModalComparativa();
      setModalAbiertoDesdeURL(true);
    }
  }, [modalAbiertoDesdeURL]);

  return (
    <>
      <MenuLateral>

        {/* Contenido principal */}
        <Grid container spacing={2} className='fondoImagenLogin2'>
          {/* Mensajes de carga o error */}
          {loadingComparativa && (
            <Grid container justifyContent="center" sx={{ mt: 3 }}>
              <CircularProgress size={80} color="secondary" />

            </Grid>
          )}

          {errorComparativa && !loadingComparativa && (
            <Grid container justifyContent="center" sx={{ mt: 3 }}>
              <Typography
                sx={{
                  fontSize: '1.8rem',
                  fontWeight: 'bold',
                  color: '#d32f2f',
                  textAlign: 'center'
                }}
              >
                {errorComparativa}
              </Typography>
            </Grid>
          )}
          <Grid
            item
            xs={12}
            sx={{
              position: 'relative',
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            {/* Solo mostrar la comparativa si no hay carga ni error */}
            {!loadingComparativa && !errorComparativa && (
              <ComparativaDesktop datosComparativa={datosComparativa} filtro={filtro} datosCargados={datosCargados} />
            )}
          </Grid>
        </Grid>
      </MenuLateral>


      <Dialog open={open} onClose={() => setOpen(false)} fullWidth maxWidth="md">
        <DialogTitle>Nueva Comparativa</DialogTitle>
        <DialogContent>
          <Grid container spacing={2}>
            <Grid item xs={12} md={4}>
              <Autocomplete
                options={productos}
                getOptionLabel={(option) => option.nomprodu || ''}
                onChange={handleChangeProducto}
                renderInput={(params) => <TextField {...params} label="Producto" />}
              />
            </Grid>
            <Grid item xs={12} md={4}>
              <Autocomplete
                options={variedades}
                getOptionLabel={(option) => option.nomvarie || ''}
                onChange={handleChangeVariedad}
                renderInput={(params) => <TextField {...params} label="Variedad" />}
              />
            </Grid>
            <Grid item xs={12} md={4}>
              <Autocomplete
                options={clientes}
                getOptionLabel={(option) => option.nomclien || ''}
                onChange={handleChangeCliente}
                renderInput={(params) => <TextField {...params} label="Cliente" />}
              />
            </Grid>
            <Grid item xs={12} md={4}>
              <LocalizationProvider dateAdapter={AdapterDayjs} adapterLocale="es">
                <DatePicker
                  views={["year"]}
                  label="AÑO"
                  value={year}
                  onChange={newYear => {
                    if (newYear) {
                      setYear(newYear);
                      setDate(date.year(newYear.year()));
                      setHDate(hDate.year(newYear.year()));
                    }
                  }}
                  slotProps={{ textField: { fullWidth: true, margin: "normal" } }}
                />
              </LocalizationProvider>
            </Grid>
            <Grid item xs={12} md={4}>
              <LocalizationProvider dateAdapter={AdapterDayjs} adapterLocale="es">
                <DatePicker
                  views={["month"]}
                  label="DESDE FECHA"
                  value={date}
                  onChange={newDate => { if (newDate) setDate(newDate.year(year.year()).date(1)); }}
                  slotProps={{ textField: { fullWidth: true, margin: "normal" } }}
                />
              </LocalizationProvider>
            </Grid>
            <Grid item xs={12} md={4}>
              <LocalizationProvider dateAdapter={AdapterDayjs} adapterLocale="es">
                <DatePicker
                  views={["month"]}
                  label="HASTA FECHA"
                  value={hDate}
                  onChange={newDate => { if (newDate) setHDate(newDate.year(year.year()).endOf("month")); }}
                  slotProps={{ textField: { fullWidth: true, margin: "normal" } }}
                />
              </LocalizationProvider>
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpen(false)}>Cancelar</Button>
          <Button onClick={() => obtenDatosComparativa(codprodu, codvarie, codclien, date, hDate)}>Crear</Button>
        </DialogActions>
      </Dialog>
    </>
  );
}
