import React, { useContext, useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import {
    AppBar,
    Grid,
    Toolbar,
    Typography,
    Tooltip,
    IconButton,
    TextField,
    Button
} from '@mui/material'
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import ArrowForwardIcon from "@mui/icons-material/ArrowForward";
import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral'
import { MensajeError } from '../../utilidades/TratamientoErrores'
import { ErrorGeneral } from '../../componentes/ErrorGeneral/ErrorGeneral';
import { LeerPedidos } from '../../servicios/Pedidos'

import { MensajeInformativo } from '../../componentes/MensajeInformativo/MensajeInformativo'
import { DataGrid, GRID_DEFAULT_LOCALE_TEXT } from '@mui/x-data-grid';
import dayjs from "dayjs";
import 'dayjs/locale/es';




export default function PedidosPagina() {
    const [hayError, setHayError] = useState(false)
    const [mensajeError, setMensajeError] = useState('')
    const [hayMensaje, setHayMensaje] = useState(false)
    const [mensaje, setMensaje] = useState('')
    const [pedidos, setPedidos] = useState([])
    //menejo de fechas
    const [date, setDate] = useState(dayjs());
    const addDay = () => setDate(date.add(1, "day"));
    const subtractDay = () => setDate(date.subtract(1, "day"));

    const handleChange = (e) => {
        setDate(dayjs(e.target.value));
    };

    const queryPedidos = useQuery({
        queryKey: ['pedidos', date.format("YYYY-MM-DD")], // ✅ la fecha entra como dependencia
        queryFn: async () => {
            try {
                // ✅ Pasamos la fecha seleccionada a LeerPedidos
                const data = await LeerPedidos(date.format("YYYY-MM-DD"));

                if (data) {
                    const pedidosLimpios = formatearPedidos(data); // limpia campos nulos
                    setPedidos(pedidosLimpios);
                    return pedidosLimpios;
                }
            } catch (error) {
                console.error('Error en queryFn:', error);
                setMensajeError(MensajeError(error));
                setHayError(true);
                throw error; // necesario para que React Query registre el error
            }
        },
        refetchInterval: 6 * 60 * 1000, // 🔁 se actualiza cada 6 minutos automáticamente
        refetchOnWindowFocus: true,     // opcional: también al volver al tab
    });

    const localeTextES = {
        noRowsLabel: 'No hay datos',
        noResultsOverlayLabel: 'No se encontraron resultados',
        errorOverlayDefaultLabel: 'Ha ocurrido un error.',
        footerRowSelected: (count) =>
            count !== 1
                ? `${count.toLocaleString()} filas seleccionadas`
                : `${count.toLocaleString()} fila seleccionada`,
        footerTotalRows: 'Total de filas:',
        MuiTablePagination: {
            labelRowsPerPage: 'Filas por página:',
            labelDisplayedRows: ({ from, to, count }) =>
                `${from}–${to} de ${count !== -1 ? count : `más de ${to}`}`,
        },
    };
    const totalRow = {
        id: 'total', // id único para la fila de totales
        kgs: pedidos.reduce((sum, row) => sum + (row.kgs || 0), 0),
        totpalet: pedidos.reduce((sum, row) => sum + (row.totpalet || 0), 0),
        numcajas: pedidos.reduce((sum, row) => sum + (row.numcajas || 0), 0)
    };


    const rowsWithTotal = [...pedidos];




    const formatearPedidos = (pedidos) => {
        return pedidos.map(p => ({
            codigo: p.codigo || '',
            codpalet: p.codpalet ?? 0,
            codtrans: p.codtrans ?? 0,
            codvarie: p.codvarie ?? 0,
            confeccion: p.confeccion || '',
            horacarga: p.horacarga || '',
            kgs: p.kgs ?? 0,
            kiloscaj: p.kiloscaj ?? 0,
            matrirem: p.matrirem || '',
            matriveh: p.matriveh || '',
            nomcalib: p.nomcalib || '',
            nomclien: p.nomclien || '',
            nompalet: p.nompalet || '',
            nomtrans: p.nomtrans || '',
            nomvarie: p.nomvarie || '',
            numcajas: p.numcajas ?? 0,
            numpedid: p.numpedid ?? 0,
            refclien: p.refclien || '',
            teltrans: p.teltrans || '',
            totpalet: p.totpalet ?? 0,
            numalbar: p.numalbar || ''
        }));
    };






    const columns = [
        { field: 'codigo', headerName: 'ID', hide: true },
        {
            field: 'kgs', headerName: 'kgs', width: 70, cellClassName: 'bold-cell', headerClassName: 'bold-header', headerAlign: 'right', align: 'right', renderHeader: (params) => (
                <div style={{ marginRight: '5px', fontWeight: 'bold' }}>
                    {params.colDef.headerName}
                </div>
            ),
        },
        { field: 'nomclien', headerName: 'Cliente', flex: 5 },
        {
            field: 'totpalet', headerName: 'Palets', minWidth: 20, headerAlign: 'right', align: 'right', renderHeader: (params) => (
                <div style={{ marginRight: '5px', fontWeight: 'normal' }}>
                    {params.colDef.headerName}
                </div>
            ),
        },
        { field: 'nompalet', headerName: 'Nom.Palet', flex: 4 },
        {
            field: 'numcajas', headerName: 'Cajas', width: 60, headerAlign: 'right', align: 'right', renderHeader: (params) => (
                <div style={{ marginRight: '5px', fontWeight: 'normal' }}>
                    {params.colDef.headerName}
                </div>
            )
        },
        {
            field: 'kiloscaj', headerName: 'Kil/caja', width: 70, headerAlign: 'right', align: 'right', renderHeader: (params) => (
                <div style={{ marginRight: '5px', fontWeight: 'normal' }}>
                    {params.colDef.headerName}
                </div>
            )
        },

        { field: 'nomvarie', headerName: 'Variedad', flex: 3 },
        { field: 'confeccion', headerName: 'Confección', flex: 6 },
        { field: 'nomcalib', headerName: 'Calibre', flex: 2 },
        { field: 'refclien', headerName: 'Referencia', minWidth: 100 },
        { field: 'nomtrans', headerName: 'Transportista', flex: 4 },
        { field: 'matriveh', headerName: 'M.vehículo', minWidth: 50 },
        { field: 'matrirem', headerName: 'M.remolque', minWidth: 50 },
        { field: 'teltrans', headerName: 'Teléfono transportista', flex: 1 },
        { field: 'horacarga', headerName: 'H.carga', minWidth: 50 }
    ]

    const columnasFormateadas = columns.map((col) => {
        const camposNumericos = ['kgs', 'totpalet', 'numcajas', 'kiloscaj'];

        if (camposNumericos.includes(col.field)) {
            return {
                ...col,
                renderCell: (params) => {
                    const valor = Number(params.value ?? 0); // aseguramos número
                    // formateo con separador de miles y 2 decimales
                    // ✅ Si es kiloscaj → 2 decimales
                    const opcionesFormato = col.field === 'kiloscaj'
                        ? { minimumFractionDigits: 2, maximumFractionDigits: 2 }
                        : { minimumFractionDigits: 0, maximumFractionDigits: 0 };

                    const valorFormateado = valor.toLocaleString('es-ES', opcionesFormato);
                    // Regex para forzar punto como separador de miles
                    const valorSeguro = valorFormateado.replace(/\B(?=(\d{3})+(?!\d))/g, ".");

                    return params.row.id === 'total'
                        ? <strong>{valorSeguro}</strong>
                        : valorSeguro;
                },
                headerAlign: 'right',
                align: 'right',
            };
        }

        return col;
    });




    return (
        <>
            <MenuLateral>
                <Grid container
                    spacing={2}
                    justifyContent="center"
                    alignItems="center"
                    className='fondoImagenLogin2'
                    sx={{
                        minHeight: '85vh', // altura completa
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: '#FFFF',

                    }}>
                    <Grid item xs={12}>
                        <AppBar id="imagen" position='static' color='secondary' >
                            <Toolbar sx={{ display: "flex", alignItems: "center", gap: 2 }}>
                                <Typography variant='h6' component='h6'>
                                    Fecha carga: {date.locale('es').format('dddd D [de] MMMM [de] YYYY')}
                                </Typography>
                                <Typography variant='h6' component='h6'>
                                    Total kilos: {totalRow.kgs.toLocaleString('es-ES')}
                                </Typography>
                                <Typography variant='h6' component='h6' sx={{ flexGrow: 1 }}>
                                    Total cajas: {totalRow.numcajas.toLocaleString('es-ES')}
                                </Typography>

                                {/* Flecha atrás */}
                                <Tooltip title="Día anterior">
                                    <IconButton color="inherit" onClick={() => setDate(date.subtract(1, "day"))}>
                                        <ArrowBackIcon />
                                    </IconButton>
                                </Tooltip>

                                {/* Campo de fecha */}
                                <TextField
                                    type="date"
                                    size="small"
                                    value={date.format("YYYY-MM-DD")}
                                    onChange={(e) => setDate(dayjs(e.target.value))}
                                    sx={{ bgcolor: "white", borderRadius: 1, input: { fontSize: 14 } }}
                                />

                                {/* Flecha adelante */}
                                <Tooltip title="Día siguiente">
                                    <IconButton color="inherit" onClick={() => setDate(date.add(1, "day"))}>
                                        <ArrowForwardIcon />
                                    </IconButton>
                                </Tooltip>
                            </Toolbar>
                        </AppBar>
                    </Grid>
                    <Grid item xs={12} sx={{ height: '75vh', width: '100%', overflow: 'hidden' }}>
                        <DataGrid
                            rows={rowsWithTotal}
                            columns={columnasFormateadas}
                            getRowId={(row) => row.id ?? row.codigo}
                            localeText={localeTextES}
                            // ❌ Elimina autoHeight
                            // autoHeight={true}
                            rowHeight={30}
                            headerHeight={50}
                            columnVisibilityModel={{
                                codigo: false,
                            }}
                            getRowClassName={(params) => {
                                if (params.row.id === 'total') return 'MuiDataGrid-row--total';
                                if (params.row.numalbar !== '') return 'fila-verde';
                                return ''; // 👈 para evitar undefined

                            }}
                            sx={{
                                borderRadius: 2,
                                boxShadow: 10,
                                border: 'none',
                                fontFamily: 'Roboto, sans-serif',
                                height: '100%', // 👈 Para que el DataGrid use todo el alto del contenedor
                                '.MuiDataGrid-virtualScroller': {
                                    overflowY: 'auto !important', // 👈 Scroll vertical interno
                                    overflowX: 'auto !important', // 👈 Scroll horizontal interno
                                },
                                '.MuiDataGrid-columnHeaders': {
                                    color: '#1723d4 !important',
                                    fontSize: 16,
                                    fontWeight: '900',
                                    borderBottom: '3px solid #90caf9',
                                },
                                '.MuiDataGrid-cell': {
                                    fontSize: 12,
                                    color: '#333',
                                },
                                '.MuiDataGrid-row': {
                                    backgroundColor: '#f9f9f9',
                                    '&:nth-of-type(even)': {
                                        backgroundColor: '#e3f2fd',
                                    },
                                },
                                '.MuiDataGrid-row:hover': {
                                    backgroundColor: '#bbdefb',
                                },
                                '.MuiDataGrid-row.Mui-selected': {
                                    backgroundColor: '#90caf9 !important',
                                    color: '#fff',
                                },
                                '.MuiDataGrid-footerContainer': {
                                    display: 'none',
                                },
                                '.MuiDataGrid-toolbarContainer': {
                                    backgroundColor: '#e3f2fd',
                                    borderBottom: '1px solid #90caf9',
                                    borderRadius: '10px 10px 10px 10px',
                                },
                                '.bold-header': {
                                    fontWeight: '900',
                                    color: '#010107ff'
                                },
                                '.bold-cell': {
                                    fontWeight: 'bold',
                                    color: '#000'
                                },
                                '.MuiDataGrid-row--total': {
                                    fontWeight: 'bold',
                                    backgroundColor: '#e0e0e0',
                                },
                                '.MuiDataGrid-overlay': {
                                    color: '#fff',      // color de letra
                                    backgroundColor: 'transparent', // opcional, si quieres fondo transparente
                                    fontSize: 16,
                                    fontWeight: 'bold',
                                },
                                '.fila-verde .MuiDataGrid-cell': {
                                    color: '#296b2fff !important', // verde oscuro
                                    fontWeight: 'bold',
                                },
                                '.fila-verde.Mui-selected .MuiDataGrid-cell': {
                                    color: '#296b2fff !important', // sigue verde incluso seleccionada
                                },
                                '.fila-verde:hover .MuiDataGrid-cell': {
                                    color: '#296b2fff !important', // sigue verde al pasar el mouse
                                },




                            }}
                        />
                    </Grid>


                </Grid>
                <ErrorGeneral hayError={hayError} mensajeError={mensajeError} cerrarError={() => setHayError(false)} />
                <MensajeInformativo hayMensaje={hayMensaje} mensaje={mensaje} cerrarMensaje={() => setHayMensaje(false)} />
            </MenuLateral>
        </>

    )
}
